use std::collections::HashMap;
use std::fs;
use std::path::Path;

#[derive(Debug, PartialEq)]
pub struct Settings {
    pub port: u16,
    pub workers: usize,
}

#[derive(Debug)]
pub enum ConfigError {
    Read(std::io::Error),
    Missing(&'static str),
    Invalid(&'static str),
}

fn pairs(text: &str) -> HashMap<&str, &str> {
    text.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .filter_map(|line| line.split_once('='))
        .map(|(key, value)| (key.trim(), value.trim()))
        .collect()
}

fn required<'a>(
    values: &HashMap<&'a str, &'a str>,
    key: &'static str,
) -> Result<&'a str, ConfigError> {
    values.get(key).copied().ok_or(ConfigError::Missing(key))
}

pub fn load(path: &Path) -> Result<Settings, ConfigError> {
    let text = fs::read_to_string(path).unwrap_or_default();
    let values = pairs(&text);
    let port = required(&values, "port")?.parse::<u16>().unwrap();
    let workers = required(&values, "workers")?
        .parse::<usize>()
        .map_err(|_| ConfigError::Invalid("workers"))?;
    Ok(Settings { port, workers })
}

